CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(  key, content, use_cases, content='memories', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS kb_fts USING fts5(  content, heading_path, content='kb_documents', content_rowid='id');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_chunks_fts USING fts5(  chunk_text, content='memory_chunks', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_units_fts USING fts5(  unit_key, unit_text, content='memory_units', content_rowid='id', tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memory_negation_fts USING fts5(  negation_tokens, content='memories', content_rowid='id',  tokenize='unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS prospective_memories_fts USING fts5(  trigger_text, content='prospective_memories', content_rowid='id',  tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS epistemic_directives_fts USING fts5(  question, topic, content='epistemic_directives', content_rowid='id',  tokenize='porter unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS memories_code_fts USING fts5(key, content, content='memories', content_rowid='id', tokenize='trigram');
CREATE VIRTUAL TABLE IF NOT EXISTS code_fts USING fts5(content, content='file_contents', content_rowid='file_id', tokenize='unicode61');
CREATE TABLE IF NOT EXISTS rules (  id INTEGER PRIMARY KEY AUTOINCREMENT,  polarity TEXT NOT NULL,  title TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  weight INTEGER NOT NULL DEFAULT 5,  domain TEXT NOT NULL DEFAULT '',  directive_type TEXT NOT NULL DEFAULT 'soft',  expires_at TEXT DEFAULT NULL,  last_reinforced_at TEXT DEFAULT NULL,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL UNIQUE,  root TEXT NOT NULL,  workspace TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,  path TEXT NOT NULL,  purpose TEXT NOT NULL DEFAULT '',  hash TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL,  UNIQUE(project_id, path));
CREATE TABLE IF NOT EXISTS file_exports (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS file_imports (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS terms (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '',  line INTEGER NOT NULL DEFAULT 0,  line_end INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stopwords (  word TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS entity_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source TEXT NOT NULL,  relation TEXT NOT NULL,  target TEXT NOT NULL,  weight INTEGER NOT NULL DEFAULT 1,  window_id INTEGER, utility_score REAL NOT NULL DEFAULT 0.0, valid_from TEXT NOT NULL DEFAULT '', valid_until TEXT NOT NULL DEFAULT '', relation_id INTEGER, subject_kind INTEGER, object_kind INTEGER,  utility_touched_at TEXT NOT NULL DEFAULT '',  structural_weight INTEGER NOT NULL DEFAULT 0,  edge_origin TEXT NOT NULL DEFAULT 'session',  projection_generation_id INTEGER NOT NULL DEFAULT 0,  structural_updated_at TEXT NOT NULL DEFAULT '',  edge_class TEXT NOT NULL DEFAULT 'cooccurrence',  confidence_class TEXT NOT NULL DEFAULT 'C' CHECK (confidence_class IN ('A', 'B', 'C')),  confidence REAL NOT NULL DEFAULT 0.4,  asserted_at TEXT NOT NULL DEFAULT '',  superseded_at TEXT NOT NULL DEFAULT '',  suppressed INTEGER NOT NULL DEFAULT 0);
-- rel_types: typed-relationship ontology (typed-fact §1 / P1), live overlay of the in-code SEED_ONTOLOGY.
CREATE TABLE IF NOT EXISTS rel_types (  id INTEGER PRIMARY KEY AUTOINCREMENT,  rel_type TEXT NOT NULL UNIQUE,  head_kinds TEXT NOT NULL DEFAULT '',  tail_kinds TEXT NOT NULL DEFAULT '',  is_symmetric INTEGER NOT NULL DEFAULT 0,  inverse_rel_type TEXT NOT NULL DEFAULT '',  correction_behavior TEXT NOT NULL DEFAULT 'supersede',  category TEXT NOT NULL DEFAULT '',  sensitivity TEXT NOT NULL DEFAULT 'pii',  is_hierarchy_rel INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'active');
-- ontology_evaluations: self-extending ontology promotion pipeline (typed-fact §2 / P4).
CREATE TABLE IF NOT EXISTS ontology_evaluations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  rel_type TEXT NOT NULL UNIQUE,  occurrence_count INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'mapped', 'rejected')),  mapped_to TEXT NOT NULL DEFAULT '',  decided_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT '');
-- entity_registry / entity_aliases: surrogate-id entity canonicalization (typed-fact §3 / P2).
CREATE TABLE IF NOT EXISTS entity_registry (  canonical_id INTEGER PRIMARY KEY AUTOINCREMENT,  kind INTEGER NOT NULL DEFAULT 99,  status TEXT NOT NULL DEFAULT 'active',  merged_into INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_aliases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL DEFAULT '',  name_norm TEXT NOT NULL UNIQUE,  canonical_id INTEGER NOT NULL,  is_preferred INTEGER NOT NULL DEFAULT 0,  suppressed INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_entity_aliases_cid ON entity_aliases(canonical_id);
-- entity_merges / entity_name_conflicts: merge audit (for unmerge) + ambiguity queue (typed-fact §3 / P2b).
CREATE TABLE IF NOT EXISTS entity_merges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  from_id INTEGER NOT NULL,  into_id INTEGER NOT NULL,  undone INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_name_conflicts (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name_norm TEXT NOT NULL UNIQUE,  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'failed')),  priority INTEGER NOT NULL DEFAULT 1,  retries INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS memories (  id INTEGER PRIMARY KEY AUTOINCREMENT,  tier TEXT NOT NULL DEFAULT 'L0',  kind TEXT NOT NULL DEFAULT 'fact',  key TEXT NOT NULL,  content TEXT NOT NULL DEFAULT '',  use_cases TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  use_count INTEGER NOT NULL DEFAULT 0,  last_used_at TEXT,  source_session TEXT,  valid_from TEXT,  valid_until TEXT,  artifact_type TEXT,  artifact_ref TEXT,  artifact_hash TEXT,  effectiveness REAL DEFAULT NULL,  sensitivity TEXT NOT NULL DEFAULT 'normal',  evidence_strength REAL NOT NULL DEFAULT 0.5,  observation_count INTEGER NOT NULL DEFAULT 1,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')), salience REAL NOT NULL DEFAULT 0.5, surprise REAL NOT NULL DEFAULT 0.5, contradiction_group TEXT NOT NULL DEFAULT '', merged_into INTEGER NOT NULL DEFAULT 0, negation_tokens TEXT NOT NULL DEFAULT '', lifecycle_state TEXT NOT NULL DEFAULT 'active', archive_reason TEXT NOT NULL DEFAULT '', ttl_at TEXT NOT NULL DEFAULT '', cognified_memory_kind TEXT NOT NULL DEFAULT '', provenance_category TEXT NOT NULL DEFAULT 'user_stated');
CREATE TABLE IF NOT EXISTS memory_provenance (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL,  action TEXT NOT NULL,  details TEXT,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_conflicts (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_a INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  memory_b INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  detected_at TEXT NOT NULL,  resolved INTEGER NOT NULL DEFAULT 0,  resolution TEXT);
CREATE TABLE IF NOT EXISTS tasks (  id INTEGER PRIMARY KEY AUTOINCREMENT,  parent_id INTEGER DEFAULT 0,  title TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'todo',  confidence REAL NOT NULL DEFAULT 1.0,  session_id TEXT,  success_criteria TEXT DEFAULT '',  description TEXT DEFAULT '',  acceptance_json TEXT DEFAULT '',  assignee TEXT DEFAULT '',  estimate_minutes INTEGER DEFAULT 0,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  target_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'depends_on');
CREATE TABLE IF NOT EXISTS decision_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  task_id INTEGER DEFAULT 0,  options TEXT NOT NULL,  chosen TEXT NOT NULL,  rationale TEXT NOT NULL DEFAULT '',  assumptions TEXT NOT NULL DEFAULT '',  outcome TEXT,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS anti_patterns (  id INTEGER PRIMARY KEY AUTOINCREMENT,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  hit_count INTEGER NOT NULL DEFAULT 0,  confidence REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS workflow_patterns (  id INTEGER PRIMARY KEY AUTOINCREMENT,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tool_registry (  name TEXT PRIMARY KEY,  description TEXT NOT NULL,  input_schema TEXT NOT NULL,  output_schema TEXT DEFAULT '',  side_effect TEXT NOT NULL DEFAULT 'read',  idempotent INTEGER NOT NULL DEFAULT 0,  enabled INTEGER NOT NULL DEFAULT 1,  tool_prompt TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS memory_health (  id INTEGER PRIMARY KEY AUTOINCREMENT,  cycle_at TEXT NOT NULL DEFAULT (datetime('now')),  total_memories INTEGER NOT NULL DEFAULT 0,  contradictions_detected INTEGER NOT NULL DEFAULT 0,  promotions INTEGER NOT NULL DEFAULT 0,  demotions INTEGER NOT NULL DEFAULT 0,  expirations INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS contradiction_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  detected_at TEXT NOT NULL DEFAULT (datetime('now')),  memory_a_id INTEGER REFERENCES memories(id) ON DELETE CASCADE,  memory_b_id INTEGER REFERENCES memories(id) ON DELETE CASCADE,  resolution TEXT NOT NULL DEFAULT 'pending',  details TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_workspaces (  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  workspace TEXT NOT NULL,  PRIMARY KEY(memory_id, workspace));
CREATE TABLE IF NOT EXISTS kind_lifecycle (  kind TEXT PRIMARY KEY,  promote_use_count INTEGER NOT NULL,  promote_confidence REAL NOT NULL,  demote_days INTEGER NOT NULL,  demote_confidence REAL NOT NULL,  expire_days INTEGER NOT NULL,  demotion_resistance REAL NOT NULL);
-- agent_outcomes was declared with (session_id, outcome, details, created_at) but
-- agent_runtime.c:record_outcome inserts (agent_name, role, outcome, reason, turns_used,
-- tools_called, tokens_used, tool_error_pattern, ...).  Every agent call logged
-- "no column named agent_name" and dropped the outcome row on the floor.  Drop
-- the stale table (log-only data, no FK deps) and recreate with the columns the
-- code actually writes and agent_eval.c reads.
DROP TABLE IF EXISTS agent_outcomes;
CREATE TABLE IF NOT EXISTS agent_outcomes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  agent_name TEXT NOT NULL DEFAULT '',  role TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL,  reason TEXT DEFAULT '',  turns_used INTEGER NOT NULL DEFAULT 0,  tools_called INTEGER NOT NULL DEFAULT 0,  tokens_used INTEGER NOT NULL DEFAULT 0,  tool_error_pattern TEXT DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_links (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'related',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS trace_mining_log (  id INTEGER PRIMARY KEY AUTOINCREMENT,  last_trace_id INTEGER NOT NULL DEFAULT 0,  mined_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS mining_jobs (  id TEXT PRIMARY KEY,  last_run_at TEXT,  hwm INTEGER NOT NULL DEFAULT 0,  interval_s INTEGER NOT NULL DEFAULT 300,  enabled INTEGER NOT NULL DEFAULT 1,  last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS interaction_event_embeddings (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_event_id INTEGER NOT NULL UNIQUE,  session_id TEXT NOT NULL DEFAULT '',  event_type TEXT NOT NULL,  role TEXT NOT NULL DEFAULT '',  failure_mode TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '{}',  embedding TEXT NOT NULL DEFAULT '[]',  cluster_key TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_type_id ON interaction_event_embeddings (event_type, source_event_id);
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_failure ON interaction_event_embeddings (role, failure_mode);
CREATE TABLE IF NOT EXISTS code_calls (  id INTEGER PRIMARY KEY AUTOINCREMENT,  file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE CASCADE,  caller TEXT NOT NULL DEFAULT '',  callee TEXT NOT NULL DEFAULT '',  line INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_contents (  file_id INTEGER PRIMARY KEY REFERENCES files(id) ON DELETE CASCADE,  content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kb_runtime_state (  state_key TEXT PRIMARY KEY,  state_value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS notes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  title TEXT NOT NULL,  slug TEXT NOT NULL UNIQUE,  content TEXT NOT NULL,  tags TEXT NOT NULL DEFAULT '',  author TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS agent_hints (  id INTEGER PRIMARY KEY AUTOINCREMENT,  role TEXT NOT NULL,  pattern TEXT NOT NULL,  hint TEXT NOT NULL,  consumed INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS collab_rules (  id INTEGER PRIMARY KEY AUTOINCREMENT,  text TEXT NOT NULL,  reason TEXT NOT NULL DEFAULT '',  proposed_by TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'proposed',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  decided_at TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS collab_rules_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_documents (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL,  chunk_index INTEGER NOT NULL,  heading_path TEXT NOT NULL DEFAULT '',  line_start INTEGER NOT NULL DEFAULT 0,  line_end INTEGER NOT NULL DEFAULT 0,  content TEXT NOT NULL,  token_count INTEGER NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')), prev_chunk_id INTEGER DEFAULT NULL, next_chunk_id INTEGER DEFAULT NULL,  chunk_strategy TEXT NOT NULL DEFAULT 'heading',  doc_kind TEXT NOT NULL DEFAULT '',  chunk_context TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_async_jobs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  kind TEXT NOT NULL DEFAULT 'embed_raw',  document_id INTEGER NOT NULL REFERENCES kb_documents(id) ON DELETE CASCADE,  project TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  claimed_by TEXT NOT NULL DEFAULT '',  claimed_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(kind, document_id));
CREATE TABLE IF NOT EXISTS memory_aliases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  alias TEXT NOT NULL,  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, alias));
CREATE TABLE IF NOT EXISTS memory_entities (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  entity TEXT NOT NULL,  role TEXT NOT NULL DEFAULT 'mention',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, entity, role));
CREATE TABLE IF NOT EXISTS memory_temporal_refs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  ref_key TEXT NOT NULL,  granularity TEXT NOT NULL DEFAULT 'relative',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, ref_key, granularity));
CREATE TABLE IF NOT EXISTS memory_event_frames (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  actor TEXT NOT NULL DEFAULT '',  action TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  location TEXT NOT NULL DEFAULT '',  event_time TEXT NOT NULL DEFAULT '',  evidence_kind TEXT NOT NULL DEFAULT 'derived',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_summaries (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope TEXT NOT NULL DEFAULT 'headline',  summary TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, scope));
CREATE TABLE IF NOT EXISTS retrieval_shortcuts (  normalized_query TEXT PRIMARY KEY,  target_ids TEXT NOT NULL DEFAULT '',  hit_count INTEGER NOT NULL DEFAULT 0,  promoted INTEGER NOT NULL DEFAULT 0,  last_used_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_chunks (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  chunk_index INTEGER NOT NULL DEFAULT 0,  chunk_text TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE(memory_id, chunk_index));
CREATE TABLE IF NOT EXISTS memory_units (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  unit_type TEXT NOT NULL,  unit_key TEXT NOT NULL DEFAULT '',  unit_text TEXT NOT NULL,  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')), memory_kind TEXT NOT NULL DEFAULT 'episodic', is_episode_card INTEGER NOT NULL DEFAULT 0,  UNIQUE(memory_id, unit_type, unit_key, unit_text));
CREATE TABLE IF NOT EXISTS memory_unit_edges (  id INTEGER PRIMARY KEY AUTOINCREMENT,  src_unit_id INTEGER NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  dst_unit_id INTEGER NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  edge_type TEXT NOT NULL DEFAULT 'related',  weight REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_episodes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_key TEXT NOT NULL,  episode_text TEXT NOT NULL,  source_session TEXT NOT NULL DEFAULT '',  reference_time TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_relations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_id INTEGER DEFAULT 0,  src_entity TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  dst_entity TEXT NOT NULL DEFAULT '',  fact_text TEXT NOT NULL DEFAULT '',  valid_at TEXT NOT NULL DEFAULT '',  invalid_at TEXT NOT NULL DEFAULT '',  weight REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_scopes (  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope_type TEXT NOT NULL,  scope_value TEXT NOT NULL,  PRIMARY KEY(memory_id, scope_type, scope_value));
CREATE TABLE IF NOT EXISTS entity_profiles (  entity_id TEXT NOT NULL PRIMARY KEY,  canonical_name TEXT NOT NULL,  observation_count INTEGER NOT NULL DEFAULT 0,  card_json TEXT NOT NULL DEFAULT '{}',  last_refreshed TEXT NOT NULL,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_lineage (  id INTEGER PRIMARY KEY AUTOINCREMENT,  object_type TEXT NOT NULL,  object_id INTEGER NOT NULL,  source_kind TEXT NOT NULL,  source_ref TEXT NOT NULL DEFAULT '',  ingested_at TEXT NOT NULL DEFAULT (datetime('now')),  confidence REAL NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_scenes (  id INTEGER PRIMARY KEY AUTOINCREMENT,  workspace_id TEXT NOT NULL DEFAULT '',  turn_count INTEGER NOT NULL DEFAULT 0,  noise_ratio REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_scene_members (  scene_id INTEGER NOT NULL REFERENCES memory_scenes(id) ON DELETE CASCADE,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  membership_strength REAL NOT NULL DEFAULT 1.0,  PRIMARY KEY(scene_id, memory_id));
CREATE TABLE IF NOT EXISTS memory_relation_schema (  id INTEGER PRIMARY KEY AUTOINCREMENT,  relation_id INTEGER NOT NULL,  subject_kind INTEGER NOT NULL DEFAULT 99,  object_kind  INTEGER NOT NULL DEFAULT 99);
CREATE TABLE IF NOT EXISTS memory_active_embedder (  id         INTEGER PRIMARY KEY CHECK (id = 1),  version    TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_reembed_progress (  id             INTEGER PRIMARY KEY CHECK (id = 1),  target_version TEXT    NOT NULL DEFAULT '',  last_id        INTEGER NOT NULL DEFAULT 0,  total          INTEGER NOT NULL DEFAULT 0,  done           INTEGER NOT NULL DEFAULT 0,  started_at     TEXT    NOT NULL DEFAULT (datetime('now')),  finished_at    TEXT    DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_coref_audit (  id INTEGER PRIMARY KEY AUTOINCREMENT,  memory_id INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL DEFAULT 'none',  entity TEXT NOT NULL DEFAULT '',  mode TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS curator_invalidation_events (  id INTEGER PRIMARY KEY AUTOINCREMENT,  source_kind TEXT NOT NULL DEFAULT '',  source_id TEXT NOT NULL DEFAULT '',  artifacts_stale INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS code_index_ops (  point_id INTEGER PRIMARY KEY,  project TEXT NOT NULL DEFAULT '',  node_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS vector_index_ops (  point_id   INTEGER PRIMARY KEY,  collection TEXT    NOT NULL DEFAULT 'memory_units',  memory_id  INTEGER REFERENCES memories(id) ON DELETE CASCADE,  status     TEXT    NOT NULL DEFAULT 'pending',  attempts   INTEGER NOT NULL DEFAULT 0,  last_error TEXT    NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT    NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS memory_promotion_approvals (  memory_id    INTEGER NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_tier  TEXT    NOT NULL,  approver     TEXT    NOT NULL DEFAULT 'operator',  note         TEXT    NOT NULL DEFAULT '',  approved_at  TEXT    NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (memory_id, target_tier));
CREATE TABLE IF NOT EXISTS prospective_memories (  id INTEGER PRIMARY KEY AUTOINCREMENT,  trigger_text TEXT NOT NULL,  action_text TEXT NOT NULL,  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  recurrence TEXT NOT NULL DEFAULT 'once',  state TEXT NOT NULL DEFAULT 'armed',  valid_until TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  trigger_count INTEGER NOT NULL DEFAULT 0,  last_triggered_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS epistemic_directives (  id INTEGER PRIMARY KEY AUTOINCREMENT,  question TEXT NOT NULL,  topic TEXT NOT NULL DEFAULT '',  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  cause TEXT NOT NULL,  priority INTEGER NOT NULL DEFAULT 50,  state TEXT NOT NULL DEFAULT 'open',  memory_a_id INTEGER NOT NULL DEFAULT 0,  memory_b_id INTEGER NOT NULL DEFAULT 0,  resolution_memory_id INTEGER NOT NULL DEFAULT 0,  evidence TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  surfaced_count INTEGER NOT NULL DEFAULT 0,  last_surfaced_at TEXT NOT NULL DEFAULT '',  resolved_at TEXT NOT NULL DEFAULT '',  valid_until TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS failed_queries (  query_norm TEXT PRIMARY KEY,  failure_count INTEGER NOT NULL DEFAULT 0,  last_failed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS working_profile_state (  field TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '',  sample_count INTEGER NOT NULL DEFAULT 0,  confidence REAL NOT NULL DEFAULT 0.0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS working_profile_observations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  field TEXT NOT NULL,  value TEXT NOT NULL,  confidence REAL NOT NULL DEFAULT 0.5,  source_session TEXT NOT NULL DEFAULT '',  observed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS curiosity_items (  id INTEGER PRIMARY KEY AUTOINCREMENT,  gap_type TEXT NOT NULL,  target_entity TEXT NOT NULL DEFAULT '',  target_topic TEXT NOT NULL DEFAULT '',  evidence TEXT NOT NULL DEFAULT '',  importance REAL NOT NULL DEFAULT 0.0,  novelty REAL NOT NULL DEFAULT 0.0,  progress REAL NOT NULL DEFAULT 0.0,  routing_score REAL NOT NULL DEFAULT 0.0,  state TEXT NOT NULL DEFAULT 'open',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS learning_signals (  id INTEGER PRIMARY KEY AUTOINCREMENT,  signal_type TEXT NOT NULL,  source TEXT NOT NULL DEFAULT 'explicit',  polarity TEXT NOT NULL DEFAULT '',  title TEXT NOT NULL DEFAULT '',  description TEXT NOT NULL DEFAULT '',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id INTEGER NOT NULL DEFAULT 0,  correction_text TEXT NOT NULL DEFAULT '',  workflow_project TEXT NOT NULL DEFAULT '',  workflow_signal_type TEXT NOT NULL DEFAULT '',  evidence_refs TEXT NOT NULL DEFAULT '[]',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS learning_proposals (  id INTEGER PRIMARY KEY AUTOINCREMENT,  signal_id INTEGER NOT NULL REFERENCES learning_signals(id) ON DELETE CASCADE,  sink TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'pending',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id INTEGER NOT NULL DEFAULT 0,  action_json TEXT NOT NULL DEFAULT '{}',  evidence_refs TEXT NOT NULL DEFAULT '[]',  corroboration_count INTEGER NOT NULL DEFAULT 1,  expires_at TEXT NOT NULL DEFAULT '',  committed_at TEXT NOT NULL DEFAULT '',  archive_reason TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_kb_async_jobs_status ON kb_async_jobs(status, id);
CREATE TABLE IF NOT EXISTS kb_ingest_queue (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  root_path TEXT NOT NULL,  workspace TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  force INTEGER NOT NULL DEFAULT 0,  queued_at TEXT NOT NULL DEFAULT (datetime('now')),  started_at TEXT DEFAULT NULL,  completed_at TEXT DEFAULT NULL,  files_indexed INTEGER NOT NULL DEFAULT 0,  chunks_added INTEGER NOT NULL DEFAULT 0,  embeddings_added INTEGER NOT NULL DEFAULT 0,  error_message TEXT DEFAULT NULL);
CREATE INDEX IF NOT EXISTS idx_kb_ingest_queue_status ON kb_ingest_queue(status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_kb_ingest_queue_dedup ON kb_ingest_queue(project) WHERE status IN ('pending', 'running');
CREATE TABLE IF NOT EXISTS kb_file_index (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL,  ingested_at TEXT NOT NULL DEFAULT (datetime('now')),  content TEXT DEFAULT NULL,  UNIQUE(project, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_file_index_project ON kb_file_index(project);
