CREATE UNIQUE INDEX IF NOT EXISTS idx_directives_dedup_contradiction  ON epistemic_directives(memory_a_id, memory_b_id)  WHERE cause = 'contradiction' AND memory_a_id != 0 AND memory_b_id != 0;
CREATE UNIQUE INDEX IF NOT EXISTS idx_directives_dedup_topic  ON epistemic_directives(cause, topic)  WHERE topic != '' AND cause IN ('retrieval_failure', 'missing_config');
CREATE INDEX IF NOT EXISTS idx_memories_cognified_kind  ON memories(cognified_memory_kind) WHERE cognified_memory_kind != '';
CREATE INDEX IF NOT EXISTS idx_working_profile_obs_field  ON working_profile_observations(field);
CREATE INDEX IF NOT EXISTS idx_working_profile_obs_field_value  ON working_profile_observations(field, value);
