CREATE INDEX IF NOT EXISTS idx_curiosity_gap_type  ON curiosity_items(gap_type);
CREATE INDEX IF NOT EXISTS idx_curiosity_target  ON curiosity_items(target_entity, target_topic)  WHERE target_entity != '' OR target_topic != '';
CREATE UNIQUE INDEX IF NOT EXISTS idx_curiosity_dedup_missing_fact  ON curiosity_items(gap_type, target_topic)  WHERE gap_type = 'missing_fact' AND target_topic != '' AND state = 'open';
CREATE INDEX IF NOT EXISTS idx_learning_signals_type  ON learning_signals(signal_type, created_at);
CREATE INDEX IF NOT EXISTS idx_learning_proposals_state  ON learning_proposals(state, sink, created_at);
CREATE INDEX IF NOT EXISTS idx_learning_proposals_target  ON learning_proposals(sink, target_key, target_memory_id)  WHERE state = 'pending';
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_ai AFTER INSERT ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(rowid, chunk_text) VALUES (new.id, new.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_ad AFTER DELETE ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(memory_chunks_fts, rowid, chunk_text)  VALUES('delete', old.id, old.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_chunks_fts_au AFTER UPDATE ON memory_chunks BEGIN  INSERT INTO memory_chunks_fts(memory_chunks_fts, rowid, chunk_text)  VALUES('delete', old.id, old.chunk_text);  INSERT INTO memory_chunks_fts(rowid, chunk_text) VALUES (new.id, new.chunk_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_ai AFTER INSERT ON memory_units BEGIN  INSERT INTO memory_units_fts(rowid, unit_key, unit_text)  VALUES (new.id, new.unit_key, new.unit_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_ad AFTER DELETE ON memory_units BEGIN  INSERT INTO memory_units_fts(memory_units_fts, rowid, unit_key, unit_text)  VALUES('delete', old.id, old.unit_key, old.unit_text);END;
CREATE TRIGGER IF NOT EXISTS memory_units_fts_au AFTER UPDATE ON memory_units BEGIN  INSERT INTO memory_units_fts(memory_units_fts, rowid, unit_key, unit_text)  VALUES('delete', old.id, old.unit_key, old.unit_text);  INSERT INTO memory_units_fts(rowid, unit_key, unit_text)  VALUES (new.id, new.unit_key, new.unit_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_ai AFTER INSERT ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(rowid, trigger_text)  VALUES (new.id, new.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_ad AFTER DELETE ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(prospective_memories_fts, rowid, trigger_text)  VALUES ('delete', old.id, old.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS prospective_fts_au AFTER UPDATE ON prospective_memories BEGIN  INSERT INTO prospective_memories_fts(prospective_memories_fts, rowid, trigger_text)  VALUES ('delete', old.id, old.trigger_text);  INSERT INTO prospective_memories_fts(rowid, trigger_text)  VALUES (new.id, new.trigger_text);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_ai AFTER INSERT ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(rowid, question, topic)  VALUES (new.id, new.question, new.topic);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_ad AFTER DELETE ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(epistemic_directives_fts, rowid, question, topic)  VALUES ('delete', old.id, old.question, old.topic);END;
CREATE TRIGGER IF NOT EXISTS directives_fts_au AFTER UPDATE ON epistemic_directives BEGIN  INSERT INTO epistemic_directives_fts(epistemic_directives_fts, rowid, question, topic)  VALUES ('delete', old.id, old.question, old.topic);  INSERT INTO epistemic_directives_fts(rowid, question, topic)  VALUES (new.id, new.question, new.topic);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_ai AFTER INSERT ON memories BEGIN  INSERT INTO memories_code_fts(rowid, key, content)  VALUES (new.id, new.key, new.content);  INSERT INTO memories_fts(rowid, key, content, use_cases)  VALUES (new.id, new.key, new.content, new.use_cases);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_ad AFTER DELETE ON memories BEGIN  INSERT INTO memories_code_fts(memories_code_fts, rowid, key, content)  VALUES('delete', old.id, old.key, old.content);  INSERT INTO memories_fts(memories_fts, rowid, key, content, use_cases)  VALUES('delete', old.id, old.key, old.content, old.use_cases);END;
CREATE TRIGGER IF NOT EXISTS memories_code_fts_au AFTER UPDATE ON memories BEGIN  INSERT INTO memories_code_fts(memories_code_fts, rowid, key, content)  VALUES('delete', old.id, old.key, old.content);  INSERT INTO memories_code_fts(rowid, key, content)  VALUES (new.id, new.key, new.content);  INSERT INTO memories_fts(memories_fts, rowid, key, content, use_cases)  VALUES('delete', old.id, old.key, old.content, old.use_cases);  INSERT INTO memories_fts(rowid, key, content, use_cases)  VALUES (new.id, new.key, new.content, new.use_cases);END;
CREATE TRIGGER IF NOT EXISTS code_fts_ai AFTER INSERT ON file_contents BEGIN  INSERT INTO code_fts(rowid, content)  VALUES (new.file_id, new.content);END;
CREATE TRIGGER IF NOT EXISTS code_fts_ad AFTER DELETE ON file_contents BEGIN  INSERT INTO code_fts(code_fts, rowid, content)  VALUES('delete', old.file_id, old.content);END;
CREATE TRIGGER IF NOT EXISTS code_fts_au AFTER UPDATE ON file_contents BEGIN  INSERT INTO code_fts(code_fts, rowid, content)  VALUES('delete', old.file_id, old.content);  INSERT INTO code_fts(rowid, content)  VALUES (new.file_id, new.content);END;
INSERT OR IGNORE INTO tool_registry VALUES('bash','Run a shell command and capture stdout/stderr.','{"type":"object","properties":{"command":{"type":"string"},    "timeout_ms":{"type":"integer"}},"required":["command"]}','','write',0,1,'');
