INSERT OR IGNORE INTO tool_registry VALUES('git_diff','Show git diff output.','{"type":"object","properties":{"path":{"type":"string"},    "ref":{"type":"string"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('git_status','Show git working tree status.','{"type":"object","properties":{"path":{"type":"string"}},    "required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('env_get','Read a specific environment variable.','{"type":"object","properties":{"name":{"type":"string"}},    "required":["name"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('test','Check file properties.','{"type":"object","properties":{"path":{"type":"string"},    "check":{"type":"string"}},"required":["path"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('request_input','Request human input during delegated execution.','{"type":"object","properties":{"question":{"type":"string"}},    "required":["question"]}','','write',0,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('code_search','Search indexed code semantically or by symbol.','{"type":"object","properties":{"query":{"type":"string"},    "project":{"type":"string"},"max_results":{"type":"integer"}},    "required":["query"]}','','read',1,1,'');
INSERT OR IGNORE INTO tool_registry VALUES('find_symbol','Look up the exact definition location of a C symbol, function, type, or macro in the indexed codebase.','{"type":"object","properties":{"identifier":{"type":"string"}},    "required":["identifier"]}','','read',1,1,'');
