CREATE TABLE IF NOT EXISTS sketch_store (  id INTEGER PRIMARY KEY AUTOINCREMENT,  sketch_kind TEXT NOT NULL,  scope_kind TEXT NOT NULL,  scope_id TEXT NOT NULL DEFAULT '',  feature_family TEXT NOT NULL,  state_bytes BLOB NOT NULL,  item_count INTEGER NOT NULL DEFAULT 0,  params_json TEXT NOT NULL DEFAULT '{}',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (sketch_kind, scope_kind, scope_id, feature_family));
CREATE TABLE IF NOT EXISTS kb_minhash_signatures (  project TEXT NOT NULL,  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL DEFAULT '',  signature_bytes BLOB NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (project, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_minhash_signatures_project ON kb_minhash_signatures(project);
CREATE TABLE IF NOT EXISTS kb_lsh_buckets (  project TEXT NOT NULL,  band INTEGER NOT NULL,  band_hash TEXT NOT NULL,  file_path TEXT NOT NULL,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (project, band, band_hash, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_lsh_buckets_lookup ON kb_lsh_buckets(project, band, band_hash);
CREATE TABLE IF NOT EXISTS artifacts (  id TEXT NOT NULL PRIMARY KEY,  kind TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'proposed',  scope_kind TEXT NOT NULL DEFAULT 'user',  scope_id TEXT NOT NULL DEFAULT '',  operator_id TEXT NOT NULL DEFAULT '',  confidence REAL NOT NULL DEFAULT 1.0,  attempt_count INTEGER NOT NULL DEFAULT 1,  source_bundle_hash TEXT NOT NULL DEFAULT '',  model_version TEXT NOT NULL DEFAULT '',  prompt_version TEXT NOT NULL DEFAULT '',  target_surface TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  committed_at TEXT NOT NULL DEFAULT '',  retired_at TEXT NOT NULL DEFAULT '',  superseded_by TEXT NOT NULL DEFAULT '',  last_accessed_at TEXT DEFAULT NULL,  last_decay_at TEXT DEFAULT NULL,  reflected_at TEXT DEFAULT NULL,  turn_id TEXT DEFAULT NULL CHECK (turn_id IS NULL OR length(turn_id) <= 128),  payload TEXT NOT NULL DEFAULT '{}');
-- This file is the FRESH-INIT shim schema (applied to a new :memory: db per test);
-- it is never applied in-place to a pre-existing db, so the inline turn_id column
-- is always present before this index. Production upgrades run via schema.sql's
-- idempotent ALTER ... ADD COLUMN IF NOT EXISTS (Postgres).
CREATE UNIQUE INDEX IF NOT EXISTS idx_artifacts_turn_event ON artifacts (turn_id) WHERE kind = 'retrieval_event' AND turn_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_artifacts_kind_state ON artifacts (kind, state);
CREATE INDEX IF NOT EXISTS idx_artifacts_scope ON artifacts (scope_kind, scope_id);
CREATE INDEX IF NOT EXISTS idx_artifacts_retrieval_attr ON artifacts (kind, scope_id);
CREATE INDEX IF NOT EXISTS idx_artifacts_demotion_profile ON artifacts (kind, target_surface, scope_kind, scope_id);
CREATE TABLE IF NOT EXISTS artifact_citations (  artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  source_kind TEXT NOT NULL,  source_id TEXT NOT NULL,  span_start INTEGER NOT NULL DEFAULT 0,  span_end INTEGER NOT NULL DEFAULT 0,  PRIMARY KEY (artifact_id, source_kind, source_id, span_start, span_end));
CREATE TABLE IF NOT EXISTS artifact_links (  from_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  to_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  kind TEXT NOT NULL,  PRIMARY KEY (from_id, to_id, kind));
CREATE TABLE IF NOT EXISTS audit_events (  id TEXT NOT NULL PRIMARY KEY,  source_artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,  target_surface TEXT NOT NULL,  target_id TEXT NOT NULL,  operator_id TEXT NOT NULL DEFAULT '',  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  before_snapshot TEXT,  after_snapshot TEXT,  applied_at TEXT NOT NULL DEFAULT (datetime('now')),  applied_confidence REAL NOT NULL DEFAULT 1.0,  flagged_for_review INTEGER NOT NULL DEFAULT 0,  reviewed_at TEXT NOT NULL DEFAULT '',  verdict TEXT NOT NULL DEFAULT '',  verdict_tag TEXT NOT NULL DEFAULT '',  verdict_scope TEXT NOT NULL DEFAULT '',  counter_example TEXT NOT NULL DEFAULT '',  verdict_note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_audit_events_artifact ON audit_events (source_artifact_id);
CREATE TABLE IF NOT EXISTS feature_rows (  subject_id TEXT NOT NULL,  subject_kind TEXT NOT NULL,  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  feature_set_version TEXT NOT NULL,  features TEXT NOT NULL DEFAULT '{}',  computed_at TEXT NOT NULL,  PRIMARY KEY (subject_id, subject_kind, feature_set_version));
CREATE INDEX IF NOT EXISTS idx_feature_rows_kind_ts ON feature_rows (subject_kind, computed_at);
CREATE TABLE IF NOT EXISTS report_enrichments (  subject_type TEXT NOT NULL,  subject_id TEXT NOT NULL,  enrichment_kind TEXT NOT NULL,  source TEXT NOT NULL DEFAULT '',  schema_version TEXT NOT NULL,  payload_json TEXT NOT NULL DEFAULT '{}',  input_hash TEXT NOT NULL DEFAULT '',  computed_at TEXT NOT NULL,  expires_at TEXT NOT NULL DEFAULT '',  PRIMARY KEY (subject_type, subject_id, enrichment_kind, source, schema_version));
CREATE INDEX IF NOT EXISTS idx_report_enrichments_subject ON report_enrichments (subject_type, subject_id);
CREATE INDEX IF NOT EXISTS idx_report_enrichments_kind_ts ON report_enrichments (enrichment_kind, computed_at);
CREATE INDEX IF NOT EXISTS idx_audit_events_surface ON audit_events (target_surface, applied_at);
CREATE TABLE IF NOT EXISTS bandit_decisions (  id TEXT NOT NULL PRIMARY KEY,  decision_point TEXT NOT NULL,  arm_id TEXT NOT NULL,  context_hash TEXT NOT NULL DEFAULT '',  propensity REAL NOT NULL DEFAULT 1.0,  reward REAL,  decided_at TEXT NOT NULL,  closed_at TEXT NOT NULL DEFAULT '',  is_exploration INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_point ON bandit_decisions (decision_point, arm_id, decided_at);
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_explore ON bandit_decisions (decision_point, decided_at, is_exploration);
CREATE TABLE IF NOT EXISTS bandit_arm_stats (  decision_point TEXT NOT NULL,  arm_id TEXT NOT NULL,  n_decisions INTEGER NOT NULL DEFAULT 0,  n_rewards INTEGER NOT NULL DEFAULT 0,  sum_reward REAL NOT NULL DEFAULT 0.0,  sum_reward_sq REAL NOT NULL DEFAULT 0.0,  posterior_alpha REAL NOT NULL DEFAULT 1.0,  posterior_beta REAL NOT NULL DEFAULT 1.0,  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (decision_point, arm_id));
CREATE TABLE IF NOT EXISTS bandit_promotions (  decision_point TEXT NOT NULL PRIMARY KEY,  arm_id TEXT NOT NULL,  rollback_arm TEXT NOT NULL DEFAULT '',  promoted_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS kb_maintenance_runs (  id TEXT NOT NULL PRIMARY KEY,  rows_decayed INTEGER NOT NULL DEFAULT 0,  orphans_pruned INTEGER NOT NULL DEFAULT 0,  elapsed_ms INTEGER NOT NULL DEFAULT 0,  lambda REAL NOT NULL DEFAULT 0.005,  confidence_floor REAL NOT NULL DEFAULT 0.10,  dry_run INTEGER NOT NULL DEFAULT 0,  run_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS docs (  id INTEGER PRIMARY KEY AUTOINCREMENT,  content_hash TEXT NOT NULL,  filename TEXT NOT NULL DEFAULT '',  scope TEXT NOT NULL DEFAULT 'global',  converter TEXT NOT NULL DEFAULT 'passthrough',  converter_version TEXT NOT NULL DEFAULT '',  normalized_text TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'staged',  review_needed INTEGER NOT NULL DEFAULT 0,  review_reason TEXT NOT NULL DEFAULT '',  doc_type TEXT NOT NULL DEFAULT '',  doc_type_confidence REAL NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (content_hash, converter, converter_version, scope));
CREATE INDEX IF NOT EXISTS idx_docs_state_review ON docs (state, review_needed);
CREATE INDEX IF NOT EXISTS idx_docs_content_hash ON docs (content_hash);
CREATE INDEX IF NOT EXISTS idx_docs_doc_type ON docs (doc_type);
CREATE TABLE IF NOT EXISTS document_sections (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  parent_id INTEGER REFERENCES document_sections(id) ON DELETE CASCADE,  ordinal INTEGER NOT NULL DEFAULT 0,  depth INTEGER NOT NULL DEFAULT 0,  heading TEXT NOT NULL DEFAULT '',  heading_path TEXT NOT NULL DEFAULT '',  span_start INTEGER NOT NULL DEFAULT 0,  span_end INTEGER NOT NULL DEFAULT 0,  content_hash TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (doc_id, heading_path, ordinal));
CREATE INDEX IF NOT EXISTS idx_document_sections_doc ON document_sections (doc_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_document_sections_parent ON document_sections (parent_id);
CREATE TABLE IF NOT EXISTS document_references (  id INTEGER PRIMARY KEY AUTOINCREMENT,  from_doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  from_section_id INTEGER REFERENCES document_sections(id) ON DELETE SET NULL,  ref_type TEXT NOT NULL DEFAULT 'mentions',  raw_target TEXT NOT NULL DEFAULT '',  to_doc_id INTEGER REFERENCES docs(id) ON DELETE SET NULL,  resolution TEXT NOT NULL DEFAULT 'unresolved',  confidence REAL NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (from_doc_id, ref_type, raw_target));
CREATE INDEX IF NOT EXISTS idx_doc_refs_from ON document_references (from_doc_id);
CREATE INDEX IF NOT EXISTS idx_doc_refs_to ON document_references (to_doc_id) WHERE to_doc_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_doc_refs_resolution ON document_references (resolution);
CREATE TABLE IF NOT EXISTS corpus_processing_jobs (  doc_id INTEGER PRIMARY KEY REFERENCES docs(id) ON DELETE CASCADE,  content_hash TEXT NOT NULL DEFAULT '',  stage TEXT NOT NULL DEFAULT 'ingested',  stage_status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  lease_owner TEXT NOT NULL DEFAULT '',  lease_until TEXT NOT NULL DEFAULT '',  last_error TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_corpus_jobs_status ON corpus_processing_jobs (stage_status, stage, doc_id);
CREATE TABLE IF NOT EXISTS corpus_stage_events (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  from_stage TEXT NOT NULL DEFAULT '',  to_stage TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL DEFAULT '',  detail TEXT NOT NULL DEFAULT '',  worker TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_corpus_stage_events_doc ON corpus_stage_events (doc_id, id);
CREATE TABLE IF NOT EXISTS document_versions (  id INTEGER PRIMARY KEY AUTOINCREMENT,  doc_key TEXT NOT NULL,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  content_hash TEXT NOT NULL DEFAULT '',  version_no INTEGER NOT NULL DEFAULT 1,  source_mtime TEXT NOT NULL DEFAULT '',  source_time TEXT NOT NULL DEFAULT '',  source_time_provenance TEXT NOT NULL DEFAULT 'unknown',  is_current INTEGER NOT NULL DEFAULT 1,  superseded_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')),  UNIQUE (doc_key, content_hash));
CREATE INDEX IF NOT EXISTS idx_document_versions_current ON document_versions (doc_key, is_current);
CREATE TABLE IF NOT EXISTS doc_releases (  id INTEGER PRIMARY KEY AUTOINCREMENT,  name TEXT NOT NULL UNIQUE,  state TEXT NOT NULL DEFAULT 'pending',  promoted_at TEXT NOT NULL DEFAULT '',  retired_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_doc_releases_state ON doc_releases (state);
CREATE TABLE IF NOT EXISTS release_docs (  release_id INTEGER NOT NULL REFERENCES doc_releases(id) ON DELETE CASCADE,  doc_id INTEGER NOT NULL REFERENCES docs(id) ON DELETE CASCADE,  accepted_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (release_id, doc_id));
CREATE INDEX IF NOT EXISTS idx_release_docs_doc_id ON release_docs (doc_id);
CREATE TABLE IF NOT EXISTS memory_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  record_type TEXT NOT NULL DEFAULT '',  primary_scope TEXT NOT NULL DEFAULT '',  workspace TEXT NOT NULL DEFAULT '',  project TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kb_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  project TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS curator_entity_vectors (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  scope_kind TEXT NOT NULL DEFAULT '',  scope_id TEXT NOT NULL DEFAULT '',  canonical_name TEXT NOT NULL DEFAULT '',  artifact_id TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_entity_vectors_scope ON curator_entity_vectors (scope_kind, scope_id);
CREATE TABLE IF NOT EXISTS curator_narrative_vectors (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT '',  doc_id TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT '',  priority TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_narrative_vectors_kind ON curator_narrative_vectors (kind, status, priority);
CREATE TABLE IF NOT EXISTS curator_claim_vectors (  point_id INTEGER PRIMARY KEY,  subj_attr_vec TEXT NOT NULL DEFAULT '[]',  value_vec TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  subject TEXT NOT NULL DEFAULT '',  attribute TEXT NOT NULL DEFAULT '',  value TEXT NOT NULL DEFAULT '',  claim_kind TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_claim_vectors_kind ON curator_claim_vectors (claim_kind);
CREATE TABLE IF NOT EXISTS curator_code_unit_vectors (  point_id INTEGER PRIMARY KEY,  intent_vec TEXT NOT NULL DEFAULT '[]',  signature_vec TEXT NOT NULL DEFAULT '[]',  body_vec TEXT NOT NULL DEFAULT '[]',  artifact_id TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  def_kind TEXT NOT NULL DEFAULT '',  signature TEXT NOT NULL DEFAULT '',  body_hash TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_kind ON curator_code_unit_vectors (def_kind);
CREATE TABLE IF NOT EXISTS exemplar_vectors (  id INTEGER PRIMARY KEY AUTOINCREMENT,  artifact_id TEXT NOT NULL,  collection TEXT NOT NULL DEFAULT 'case_exemplars',  embedding TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_artifact_id ON exemplar_vectors (artifact_id);
CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_collection  ON exemplar_vectors (collection);
CREATE TABLE IF NOT EXISTS evidence_vectors (  id INTEGER PRIMARY KEY AUTOINCREMENT,  artifact_id TEXT NOT NULL,  collection TEXT NOT NULL DEFAULT 'evidence',  embedding TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_evidence_vectors_artifact_id ON evidence_vectors (artifact_id);
CREATE INDEX IF NOT EXISTS idx_evidence_vectors_collection  ON evidence_vectors (collection);
CREATE TABLE IF NOT EXISTS reasoning_rulesets (  id TEXT NOT NULL PRIMARY KEY,  version INTEGER NOT NULL DEFAULT 1,  name TEXT NOT NULL DEFAULT '',  content_hash TEXT NOT NULL DEFAULT '',  active INTEGER NOT NULL DEFAULT 1,  rules TEXT NOT NULL DEFAULT '[]',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_reasoning_rulesets_active ON reasoning_rulesets (active, name);
CREATE TABLE IF NOT EXISTS memory_recall_shadow_deltas (  id INTEGER PRIMARY KEY AUTOINCREMENT,  query_hash TEXT NOT NULL,  project TEXT NOT NULL DEFAULT '',  mode TEXT NOT NULL DEFAULT 'shadow',  result_count INTEGER NOT NULL DEFAULT 0,  delta_json TEXT NOT NULL DEFAULT '{}',  created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_mrsd_query_created ON memory_recall_shadow_deltas(query_hash, created_at);
CREATE INDEX IF NOT EXISTS idx_mrsd_project_created ON memory_recall_shadow_deltas(project, created_at);
CREATE TABLE IF NOT EXISTS entity_nodes (  node_key TEXT PRIMARY KEY,  node_kind INTEGER NOT NULL DEFAULT 0,  project TEXT NOT NULL DEFAULT '',  display_name TEXT NOT NULL DEFAULT '',  full_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  node_origin TEXT NOT NULL DEFAULT '',  last_seen_generation_id INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_entity_nodes_project ON entity_nodes(project);
CREATE INDEX IF NOT EXISTS idx_entity_nodes_kind ON entity_nodes(node_kind);
CREATE TABLE IF NOT EXISTS entity_node_aliases (  alias TEXT NOT NULL,  node_key TEXT NOT NULL REFERENCES entity_nodes(node_key) ON DELETE CASCADE,  alias_kind TEXT NOT NULL DEFAULT '',  project TEXT NOT NULL DEFAULT '',  last_seen_generation_id INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (datetime('now')),  PRIMARY KEY (alias, node_key));
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_alias ON entity_node_aliases(alias);
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_project_alias ON entity_node_aliases(project, alias);
CREATE TABLE IF NOT EXISTS code_projection_generations (  id INTEGER PRIMARY KEY AUTOINCREMENT,  project TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','visible','superseded','aborted')),  source_hash TEXT NOT NULL DEFAULT '',  edge_count INTEGER NOT NULL DEFAULT 0,  node_count INTEGER NOT NULL DEFAULT 0,  started_at TEXT NOT NULL DEFAULT (datetime('now')),  visible_at TEXT NOT NULL DEFAULT '',  aborted_at TEXT NOT NULL DEFAULT '',  error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_cpg_project_state ON code_projection_generations(project, state);
CREATE TABLE IF NOT EXISTS code_projection_edges (  generation_id INTEGER NOT NULL REFERENCES code_projection_generations(id) ON DELETE CASCADE,  project TEXT NOT NULL,  source TEXT NOT NULL,  relation TEXT NOT NULL,  target TEXT NOT NULL,  source_hash TEXT NOT NULL DEFAULT '',  PRIMARY KEY (generation_id, source, relation, target));
CREATE INDEX IF NOT EXISTS idx_cpe_project_triple ON code_projection_edges(project, source, relation, target);
CREATE INDEX IF NOT EXISTS idx_ee_source_relation ON entity_edges(source, relation);
CREATE INDEX IF NOT EXISTS idx_ee_target_relation ON entity_edges(target, relation);
CREATE INDEX IF NOT EXISTS idx_ee_origin_source ON entity_edges(edge_origin, source);
CREATE INDEX IF NOT EXISTS idx_ee_projection_generation ON entity_edges(projection_generation_id, source, relation);
CREATE TABLE IF NOT EXISTS code_embeddings (  point_id INTEGER PRIMARY KEY,  embedding TEXT NOT NULL DEFAULT '[]',  project TEXT NOT NULL DEFAULT '',  node_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  record_type TEXT NOT NULL DEFAULT 'code_unit',  content_hash TEXT NOT NULL DEFAULT '',  body_hash TEXT NOT NULL DEFAULT '',  source_hash TEXT NOT NULL DEFAULT '',  payload_json TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_code_embeddings_project ON code_embeddings(project);
CREATE INDEX IF NOT EXISTS idx_code_embeddings_node ON code_embeddings(project, node_key);
CREATE UNIQUE INDEX IF NOT EXISTS idx_code_embeddings_hash ON code_embeddings(project, node_key, content_hash);
CREATE INDEX IF NOT EXISTS idx_code_embeddings_body_hash ON code_embeddings(project, body_hash);
